use super::*;
/// 🏭️ The actual Drawing catalog declares every constructor currency and retains one shared semantic source.
#[test]
fn original_drawing_catalog_prices_real_wire_and_shared_semantic_sources(){
 let d=DrawingMemberStoreProducer::source_demands().unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};for axis in[0,1,2,4]{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,2=>denied.maximum_capacity_bytes=d.capacity_bytes-1,_=>denied.maximum_depth=d.depth-1}let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||DrawingMemberStoreProducer::admit_sources(denied));let rejected=match result{Err(rejected)=>rejected,Ok(_)=>panic!("denied original catalog admitted")};assert!(rejected.owners.is_none());assert_eq!(rejected.progress,Default::default());assert_eq!((born,released),(0,0));}
 let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||DrawingMemberStoreProducer::admit_sources(g));let(mut owners,p)=match result{Ok(v)=>v,Err(_)=>panic!("full original catalog refused")};assert!(p.fits(g));assert_eq!((born,released),(p.retained_capacity_bytes,p.released_bytes));assert!(owners.original_semantic_issuer_is_shared());assert!(owners.one_item_wire_preparation.is_some());for _ in 0..10000{let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};let(step,born,released)=semio_framework_trace_memory_testing::observe_backing(||owners.close_uninstalled_owners_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((born,released),(step.progress().retained_capacity_bytes,step.progress().released_bytes));if matches!(step,semio_framework_value::retained_clone::RetainedCloneStep::Complete(_)){return}}panic!("actual Drawing catalog failed to close")
}

struct DrawingWireConstruction(RetainedCloneGrant);
impl semio_framework_value_native_owned::native_decoding::NativeDecodeConstructionRecipient for DrawingWireConstruction{
 fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{if !semio_framework_value::retained_clone::retained_clone_grant_admits(self.0,d){return Err(ValueError::literal(semio_framework_value::ValueRefusalKind::OwnershipLimit,"original Drawing wire fixture demand is not funded"))}Ok(self.0)}
 fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{assert!(p.fits(g));Ok(())}
}
/// 📨️ Actual aggregate Drawing commands pass the original canonical receiver and return its exact installed issuer.
#[test]
fn original_drawing_wire_receives_actual_mutations_without_a_cold_decoder(){
 use semio_framework_value::{retained_clone::{RetainedCloneSource,RetainedCloneStep},ErasedSnapshotRetirement};use semio_framework_value_native_owned::native_decoding::{NativeDecodeControl,NativeDecodeRetirementRecipient};
 for original in[serde_json::json!({"mutation":"setArtboard","artboard":{"width":800.0,"height":600.0}}),serde_json::json!({"mutation":"setLayerVisible","layerId":"shape-original","visible":false})]{
  let d=DrawingMemberStoreProducer::source_demands().unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};let(mut catalog,_)=match DrawingMemberStoreProducer::admit_sources(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_depth:d.depth,..g}){Ok(v)=>v,Err(_)=>panic!("actual Drawing catalog refused")};let issuer=catalog.mutation_retirement.as_ref().unwrap();let mut octets=b"op".to_vec();let typed:DrawingMutation=serde_json::from_value(original.clone()).unwrap();octets.extend(serde_json::to_vec(&typed).unwrap());let pointer=octets.as_ptr();let(mut source,_)=RetainedCloneSource::admit_owned(octets,(),g).map_err(|(e,..)|e).unwrap();let(projection,_)=source.retain_original(g).unwrap();assert_eq!(projection.borrow().unwrap().get().as_ptr(),pointer);let mut observer=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut c=NativeDecodeControl::new_retained(&mut observer);c.install_retirement_recipient(&mut recipient).unwrap();let ledger=c.ledger_identity();let identity=c.retirement_recipient_identity();let(mut receiver,_)=semio_framework_pack_json::OriginalJsonReceiving::<DrawingMutation>::admit(projection,issuer,b"op",|m|m,&c,g).map_err(|(e,_)|e).unwrap();
  for _ in 0..100000{if receiver.ready(){break}let mut construction=DrawingWireConstruction(g);c.with_construction_recipient(&mut construction,|c|receiver.advance(c,65536,g)).unwrap();}assert!(receiver.ready());let mut received=None;for _ in 0..100000{let(_,value)=receiver.take_original(&mut c,65536,g).unwrap();if let Some((value,source))=value{assert!(Arc::ptr_eq(&source,issuer));assert_eq!(serde_json::to_value(&value).unwrap(),original);received=Some((value,source));break}}assert!(received.is_some());
  for _ in 0..100000{if receiver.terminal_is_empty(){break}c.with_retirement(g,|o|o.with_original_close(|o|{assert_eq!(o.ledger_identity(),ledger);assert_eq!(o.retirement_recipient_identity(),identity);receiver.close_step(o,g)})).unwrap();}assert!(receiver.terminal_is_empty());for _ in 0..100000{if source.terminal_is_empty(){break}source.close_step(g).unwrap();}assert!(source.terminal_is_empty());let(value,source)=received.take().unwrap();let(mut retirement,_)=source.retire_owned(value,g).map_err(|(e,_)|e).unwrap();for _ in 0..100000{if retirement.terminal_is_empty(){break}retirement.close_step(g).unwrap();}assert!(retirement.terminal_is_empty());let mut authority=semio_framework_value::FactoryAuthority::new(source);for _ in 0..100000{if authority.terminal_is_empty(){break}authority.step(g).unwrap();}assert!(authority.terminal_is_empty());drop(c);assert!(recipient.terminal_is_empty());for _ in 0..100000{if matches!(catalog.close_uninstalled_owners_step(g).unwrap(),RetainedCloneStep::Complete(_)){break}}
 }
}
